  public Window Window{get{return win;}}
  public static readonly string[] SourceKeys={"google_ads","naver_ads","google_search","naver_search","naver_blog","naver_cafe","social","referral","direct","unknown"};
  public static readonly string[] SourceNames={"구글 광고","네이버 광고","구글 검색","네이버 검색","네이버 블로그","네이버 카페","SNS·당근","다른 사이트","직접 방문","이전 기록·미분류"};
  public static readonly string[] TableKeys={"requests","day_notes","finances","flags","legacy_notes","daily_stats","sources","visitors"};
  public static readonly string[] TableNames={"수거 신청서","날짜별 메모","하루 금액","단골·블랙리스트","이전 고객 메모","일별 홈페이지 통계","유입 경로 통계","일별 방문자 통계"};
  static readonly string[] Titles={"오늘의 현황","유입 분석","사이트 상태","수거 신청서","데이터 관리"};
  static readonly string[] Hints={"방문부터 문의까지, 오늘의 흐름을 확인하세요.","어디에서 들어와 전화했는지 확인하세요.","접속 상태와 관리자 연결을 확인하세요.","검색하고, 확인하고, 수거 업무를 처리하세요.","저장된 업무 자료를 조회하고 파일로 백업하세요."};
  static readonly string[] Glyphs={"\uE80F","\uE9D9","\uE7F4","\uE8A5","\uE8B7"};
  public Desk(bool preview=false){
   demo=preview;
   using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Shell.xaml"))win=(Window)XamlReader.Load(stream);
   content=(Grid)win.FindName("Content");nav=(StackPanel)win.FindName("Navigation");status=(TextBlock)win.FindName("Status");title=(TextBlock)win.FindName("PageTitle");subtitle=(TextBlock)win.FindName("Subtitle");progress=(ProgressBar)win.FindName("Progress");month=(ComboBox)win.FindName("Month");reload=(Button)win.FindName("Reload");
   var logo=(Image)win.FindName("Logo");using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Logo.png")){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.StreamSource=stream;image.EndInit();logo.Source=image;}
   win.Icon=logo.Source;
   for(int i=0;i<24;i++)month.Items.Add(KoreaNow().AddMonths(-i).ToString("yyyy-MM"));month.SelectedIndex=0;
   month.SelectionChanged+=async(s,e)=>{if(!initial){sourceToday=false;await Run(Refresh);}};
   reload.Click+=async(s,e)=>await Run(Refresh);
   ((Button)win.FindName("OpenSite")).Click+=(s,e)=>Process.Start(Api.Origin);
   ((Button)win.FindName("Logout")).Click+=(s,e)=>{if(Confirm("로그아웃할까요?","이 PC에 저장된 로그인 정보도 지워집니다.")){api.Token="";Session.Clear();ShowLogin();}};
   timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(60)};timer.Tick+=async(s,e)=>{if(!busy&&!String.IsNullOrEmpty(api.Token)&&page<3)await Run(Refresh);};
   win.Closed+=(s,e)=>{timer.Stop();api.Dispose();};
   BuildNav();initial=false;
   if(demo){api.Token="demo-only";DemoData();Render();SetStatus("미리보기 · 모든 데이터는 예시입니다. 서버에 접속하지 않습니다.",false);}
   else{api.Token=Session.Load();if(String.IsNullOrEmpty(api.Token))ShowLogin();else win.Loaded+=async(s,e)=>await Run(Refresh);timer.Start();}
  }
  static DateTime KoreaNow(){return DateTime.UtcNow.AddHours(9);}
  string Month{get{return Convert.ToString(month.SelectedItem);}}
  static Brush Brush(string color){return (Brush)new BrushConverter().ConvertFromString(color);}
  static TextBlock Text(string value,double size=14,string color="#18334E",bool bold=false){return new TextBlock{Text=value,FontSize=size,Foreground=Brush(color),FontWeight=bold?FontWeights.Bold:FontWeights.Normal,TextWrapping=TextWrapping.Wrap};}
  static StackPanel Stack(){return new StackPanel();}
  static StackPanel Row(){return new StackPanel{Orientation=Orientation.Horizontal};}
  static Border Card(UIElement body,double padding=20){return new Border{Background=Brush("#FFFFFF"),CornerRadius=new CornerRadius(12),Padding=new Thickness(padding),Child=body,Margin=new Thickness(0,0,0,16)};}
  static void Gap(Panel p,UIElement item,double top=10){var f=item as FrameworkElement;if(f!=null)f.Margin=new Thickness(0,top,0,0);p.Children.Add(item);}
  Button Btn(string text,Action action,bool primary=false){var b=new Button{Content=text,Background=Brush(primary?"#18334E":"#EAF0F7"),Foreground=Brush(primary?"#FFFFFF":"#18334E")};b.Click+=(s,e)=>action();return b;}
  Button AsyncBtn(string text,Func<Task> action,bool primary=false){return Btn(text,async()=>await Run(action),primary);}
  static string Num(long n){return n.ToString("N0");}
  static bool Yes(Dictionary<string,object> o,string key){return Json.S(o,key).Equals("true",StringComparison.OrdinalIgnoreCase);}
  void SetStatus(string message,bool error){status.Text=message;status.Foreground=Brush(error?"#B3261E":"#36536E");}
  async Task Run(Func<Task> action){if(busy)return;busy=true;nav.IsEnabled=false;reload.IsEnabled=false;month.IsEnabled=false;((Button)win.FindName("Logout")).IsEnabled=false;progress.Visibility=Visibility.Visible;content.IsEnabled=false;
   try{await action();}catch(LoginExpired){api.Token="";Session.Clear();ShowLogin();SetStatus("로그인이 만료되었습니다. 기존 관리자 비밀번호로 다시 로그인해 주세요.",true);}catch(Exception e){SetStatus(e is TaskCanceledException?"연결 시간이 초과되었습니다. 이전 화면을 유지합니다. 새로고침해 주세요.":e.Message,true);}
   finally{busy=false;nav.IsEnabled=true;reload.IsEnabled=!String.IsNullOrEmpty(api.Token);month.IsEnabled=reload.IsEnabled;((Button)win.FindName("Logout")).IsEnabled=true;progress.Visibility=Visibility.Collapsed;content.IsEnabled=true;}
  }
  void BuildNav(){nav.Children.Clear();for(int i=0;i<Titles.Length;i++){int index=i;var r=Row();r.Children.Add(new TextBlock{Text=Glyphs[i],FontFamily=new FontFamily("Segoe MDL2 Assets"),FontSize=18,Foreground=Brush(i==page?"#FFFFFF":"#A6BBD0"),Margin=new Thickness(0,0,12,0)});r.Children.Add(Text(Titles[i],14,i==page?"#FFFFFF":"#CAD8E5",true));var b=Btn("",async()=>{if(String.IsNullOrEmpty(api.Token)){ShowLogin();return;}page=index;BuildNav();await Run(Refresh);});b.Content=r;b.Background=Brush(i==page?"#31546F":"#16324C");b.Margin=new Thickness(0,0,0,8);b.HorizontalContentAlignment=HorizontalAlignment.Left;nav.Children.Add(b);}}
  void ShowLogin(){content.Children.Clear();requests.Clear();overview.Clear();probe.Clear();title.Text="관리자 로그인";subtitle.Text="기존 안드로이드 앱과 같은 관리자 비밀번호를 사용합니다.";reload.IsEnabled=false;month.IsEnabled=false;
   var form=Stack();form.Children.Add(Text("헌옷일번지 관리자 데스크",25,"#18334E",true));Gap(form,Text("방문 통계와 수거 업무를 PC에서 편하게 관리하세요.",14,"#647A8C"),12);Gap(form,Text("관리자 비밀번호",13,"#52687B",true),28);
   var password=new PasswordBox{Padding=new Thickness(12),FontSize=16,MaxLength=200};Gap(form,password,8);var remember=new CheckBox{Content="이 Windows 계정에서 로그인 유지",IsChecked=true,Margin=new Thickness(0,18,0,18)};form.Children.Add(remember);
   var login=AsyncBtn("로그인",async()=>{if(password.Password.Length==0)throw new Exception("관리자 비밀번호를 입력해 주세요.");var result=await api.Call("/api/admin/native-login","POST",Json.Obj("password",password.Password));password.Clear();api.Token=Json.S(result,"token");if(String.IsNullOrEmpty(api.Token))throw new Exception("로그인 응답을 확인해 주세요.");if(remember.IsChecked==true)Session.Save(api.Token);else Session.Clear();await Refresh();},true);form.Children.Add(login);password.KeyDown+=(s,e)=>{if(e.Key==System.Windows.Input.Key.Enter)login.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};
   Gap(form,Text("비밀번호는 저장하지 않습니다. 로그인 유지 정보는 현재 Windows 사용자에게만 열리는 암호화 저장소에 보관합니다.",12,"#647A8C"),20);var card=Card(form,32);card.Width=470;card.HorizontalAlignment=HorizontalAlignment.Center;card.VerticalAlignment=VerticalAlignment.Center;content.Children.Add(card);SetStatus("안전한 관리자 연결 · https://1beonji.com",false);
  }
  async Task Refresh(){
   if(demo){Render();return;}if(String.IsNullOrEmpty(api.Token)){ShowLogin();return;}
   SetStatus("최신 데이터를 확인하고 있습니다…",false);
   if(page<3){
    overview=await api.Call("/api/admin/desktop?month="+Month);
    try{probe=await api.Probe();}catch{probe=Json.Obj("ok",false,"http",0,"ms",0);}
    healthLog.Insert(0,Json.Obj("time",KoreaNow().ToString("MM-dd HH:mm:ss"),"status",Yes(probe,"ok")?"접속 정상":"접속 확인 필요","ms",Json.N(probe,"ms")));if(healthLog.Count>100)healthLog.RemoveAt(100);
   }else if(page==3)requests=Json.Rows(await api.Call("/api/admin/native-requests"),"requests");
   else tableData=await api.Call("/api/admin/desktop?mode=data&table="+tableKey+"&page="+tablePage);
   Render();SetStatus("마지막 확인 "+KoreaNow().ToString("yyyy.MM.dd HH:mm:ss")+" · "+(page<3&&!Yes(probe,"ok")?"홈페이지 접속 상태를 확인해 주세요.":"서버 연결됨"),page<3&&!Yes(probe,"ok"));
  }
  void Render(){title.Text=Titles[page];subtitle.Text=Hints[page];content.Children.Clear();if(page==0)Overview();else if(page==1)Traffic();else if(page==2)Health();else if(page==3)Requests();else Database();}
  void ScrollBody(Panel body){var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};content.Children.Add(scroll);}
  UIElement Metrics(params object[] values){var grid=new Grid{Margin=new Thickness(0,0,0,16)};for(int i=0;i<values.Length;i+=3){grid.ColumnDefinitions.Add(new ColumnDefinition());var panel=Stack();panel.Children.Add(Text(Convert.ToString(values[i]),13,"#647A8C"));Gap(panel,Text(Convert.ToString(values[i+1]),30,"#18334E",true),9);Gap(panel,Text(Convert.ToString(values[i+2]),11,"#647A8C"),9);var c=Card(panel,18);c.Margin=new Thickness(0,0,i==values.Length-3?0:12,0);Grid.SetColumn(c,i/3);grid.Children.Add(c);}return grid;}
  long RequestCount(string key){return Json.Rows(overview,"requestCounts").Where(r=>Json.S(r,"status")==key).Sum(r=>Json.N(r,"count"));}
  void Overview(){var body=Stack();var today=Json.D(overview,"todaySummary");body.Children.Add(Metrics("오늘 방문자",Num(Json.N(today,"visitors")),"기기·브라우저 기준","오늘 조회수",Num(Json.N(today,"views")),"새로고침·재방문 포함","전화 버튼 클릭",Num(Json.N(today,"phoneClicks")),"실제 통화 연결 수 아님","온라인 신청",Num(Json.N(today,"requests")),"오늘 접수 완료"));
   var top=Row();top.Children.Add(Text("오늘 "+Json.S(overview,"today"),17,"#18334E",true));body.Children.Add(Card(top,16));
   var chart=Stack();chart.Children.Add(Text(Month+" · 일별 홈페이지 조회",18,"#18334E",true));Gap(chart,Chart(Json.Rows(overview,"days")),18);Gap(chart,Text("선택한 달의 조회수 "+Num(Json.N(Json.D(overview,"totals"),"views"))+"회 · 전화 버튼 "+Num(Json.N(Json.D(overview,"totals"),"phoneClicks"))+"회 · 온라인 신청 "+Num(Json.N(Json.D(overview,"totals"),"requests"))+"건",12,"#647A8C"),12);body.Children.Add(Card(chart));
   body.Children.Add(Metrics("새 신청",Num(RequestCount("new")),"상담을 기다리고 있어요","연락 완료",Num(RequestCount("contacted")),"수거 일정을 확인하세요","처리 완료",Num(RequestCount("done")),"현재 저장된 신청서 기준"));
   var notice=Stack();notice.Children.Add(Text("읽기 전에 확인해 주세요",15,"#18334E",true));Gap(notice,Text("방문자·광고 유입 집계 시작: "+Json.S(overview,"acquisitionStartedAt")+". 이전 기록은 새 통계로 복원되지 않습니다. 같은 사람이 다른 기기를 쓰면 별도로 집계되며, 저장·광고 차단으로 일부 방문이 누락될 수 있습니다.",12,"#647A8C"),8);body.Children.Add(Card(notice));ScrollBody(body);
  }
  UIElement Chart(List<Dictionary<string,object>> rows){var ordered=rows.OrderBy(r=>Json.S(r,"date")).ToList();var grid=new Grid{Height=150};long max=Math.Max(1,ordered.Count==0?0:ordered.Max(r=>Json.N(r,"views")));int i=0;foreach(var row in ordered){grid.ColumnDefinitions.Add(new ColumnDefinition());var p=new Grid();p.RowDefinitions.Add(new RowDefinition());p.RowDefinitions.Add(new RowDefinition{Height=new GridLength(22)});var bar=new Border{Background=Brush("#3D83B4"),CornerRadius=new CornerRadius(4,4,0,0),Height=Math.Max(2,120d*Json.N(row,"views")/max),VerticalAlignment=VerticalAlignment.Bottom,Margin=new Thickness(3,0,3,0),ToolTip=Json.S(row,"date")+" · "+Num(Json.N(row,"views"))+"회"};p.Children.Add(bar);var date=Json.S(row,"date");var t=Text(date.Length>=10?date.Substring(8):date,10,"#647A8C");t.HorizontalAlignment=HorizontalAlignment.Center;Grid.SetRow(t,1);p.Children.Add(t);Grid.SetColumn(p,i++);grid.Children.Add(p);}return grid;}
  static string SourceName(string key){int i=Array.IndexOf(SourceKeys,key);return i<0?"미분류":SourceNames[i];}
  void Traffic(){var root=new DockPanel();var heading=Stack();var row=Row();row.Children.Add(Btn("선택한 달",()=>{sourceToday=false;Render();},!sourceToday));row.Children.Add(Btn("오늘",()=>{sourceToday=true;Render();},sourceToday));row.Children.Add(Btn("광고 링크 만들기",AdLinks));heading.Children.Add(row);Gap(heading,Text("광고 클릭 식별자 또는 UTM 태그 기준의 유입입니다. 광고비·노출수·실제 통화 연결은 집계하지 않습니다. 경로가 지워진 방문은 검색/직접 방문으로 분류될 수 있습니다.",12,"#647A8C"),12);heading.Margin=new Thickness(0,0,0,16);DockPanel.SetDock(heading,Dock.Top);root.Children.Add(heading);
   var items=new List<Dictionary<string,object>>();var sources=Json.Rows(overview,"sources");foreach(var key in SourceKeys){var found=sources.Where(r=>Json.S(r,"source")==key&&(!sourceToday||Json.S(r,"date")==Json.S(overview,"today")));items.Add(Json.Obj("source",SourceName(key),"views",found.Sum(r=>Json.N(r,"views")),"phoneClicks",found.Sum(r=>Json.N(r,"phoneClicks"))));}
   var grid=GridFor(items.OrderByDescending(r=>Json.N(r,"views")).ToList(),new[]{"source","views","phoneClicks"},new[]{"유입 경로","조회수","전화 버튼 클릭"});root.Children.Add(Card(grid,0));content.Children.Add(root);
  }
  void AdLinks(){var w=Dialog("광고 유입을 구분하는 링크",620,480);var p=(StackPanel)((ScrollViewer)w.Content).Content;
   p.Children.Add(Text("광고의 최종 도착 URL에 사용하세요.",19,"#18334E",true));Gap(p,Text("구글 자동 태그(gclid 등)와 네이버 자동추적 URL이 있으면 자동 구분됩니다. 태그가 없는 광고는 아래 링크를 사용할 수 있습니다. 실제 광고 설정은 각 광고 관리자에서 변경해야 합니다.",13,"#647A8C"),12);
   foreach(string source in new[]{"google","naver"}){Gap(p,Text(source=="google"?"구글 광고":"네이버 광고",14,"#18334E",true),20);string link=Api.Origin+"/?utm_source="+source+"&utm_medium=cpc&utm_campaign=pickup";var box=new TextBox{Text=link,IsReadOnly=true,TextWrapping=TextWrapping.Wrap};Gap(p,box,8);Gap(p,Btn("링크 복사",()=>{Clipboard.SetText(link);}),8);}w.ShowDialog();}
  void Health(){var body=Stack();var h=Json.D(overview,"health");body.Children.Add(Metrics("홈페이지 접속",Yes(probe,"ok")?"정상":"확인 필요",Json.N(probe,"http")==0?"연결 실패":"HTTP "+Json.N(probe,"http"),"응답 시간",Num(Json.N(probe,"ms"))+" ms","이 PC에서 홈페이지 접속 기준","데이터베이스",Yes(h,"database")?"연결됨":"확인 필요","관리자 API 응답 기준"));
   var p=Stack();p.Children.Add(Text("주요 기능 점검",18,"#18334E",true));Gap(p,Text("온라인 신청 설정  ·  "+(Yes(h,"onlineForm")&&Yes(probe,"configuration")?"응답 정상":"확인 필요")),16);Gap(p,Text("신청서 화면·스크립트  ·  "+(Yes(probe,"form")&&Yes(probe,"scripts")?"확인됨":"확인 필요")),12);Gap(p,Text("앱 알림 설정  ·  "+(Yes(h,"pushConfigured")?"설정됨":"확인 필요")),12);Gap(p,Text("설정 확인은 실제 신청·푸시 전송 성공을 보장하지 않습니다. 이 점검은 시험 신청이나 문자를 보내지 않습니다. 프로그램을 실행하는 동안 60초마다 확인합니다.",12,"#647A8C"),18);body.Children.Add(Card(p));body.Children.Add(Text("이번 실행 중 점검 기록",17,"#18334E",true));var grid=GridFor(healthLog,new[]{"time","status","ms"},new[]{"확인 시각 (한국 시간)","홈페이지 상태","응답 시간 (ms)"});grid.Height=260;Gap(body,Card(grid,0),12);ScrollBody(body);}
  DataGrid GridFor(List<Dictionary<string,object>> rows,string[] keys,string[] labels){var grid=new DataGrid();var table=new DataTable();foreach(string key in keys)table.Columns.Add(key,typeof(string));foreach(var record in rows){var row=table.NewRow();foreach(string key in keys){var value=Json.S(record,key);if((key=="created_at"||key=="updated_at"||key=="last_activity_at")&&Json.N(record,key)>0)value=new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(Json.N(record,key)).AddHours(9).ToString("yy.MM.dd HH:mm");row[key]=value;}table.Rows.Add(row);}for(int i=0;i<keys.Length;i++){var style=new Style(typeof(TextBlock));style.Setters.Add(new Setter(TextBlock.VerticalAlignmentProperty,VerticalAlignment.Center));style.Setters.Add(new Setter(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis));grid.Columns.Add(new DataGridTextColumn{Header=labels[i],Binding=new Binding("["+keys[i]+"]"),Width=new DataGridLength(keys[i]=="address"||keys[i]=="content"||keys[i]=="admin_note"?2:1,DataGridLengthUnitType.Star),MinWidth=90,ElementStyle=style});}grid.ItemsSource=table.DefaultView;grid.MouseDoubleClick+=(s,e)=>{var r=grid.SelectedItem as DataRowView;if(r!=null){string data=String.Join("\n\n",keys.Select((k,i)=>labels[i]+"\n"+Convert.ToString(r[k])));var w=Dialog("자료 상세 보기",680,600);var p=(StackPanel)((ScrollViewer)w.Content).Content;var box=new TextBox{Text=data,IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,BorderThickness=new Thickness(0)};p.Children.Add(box);w.ShowDialog();}};return grid;}
  Dictionary<string,object> SelectedRequest(){var r=currentGrid==null?null:currentGrid.SelectedItem as DataRowView;if(r==null)return null;return requests.FirstOrDefault(v=>Json.S(v,"id")==Convert.ToString(r["id"]));}
