  static string ColumnName(string name){var names=new Dictionary<string,string>{{"id","ID"},{"name","성함"},{"phone","연락처"},{"address","주소"},{"date","날짜"},{"amount","수거량"},{"status","처리 상태"},{"time_slot","희망 시간대"},{"pickup_method","수거 방식"},{"message","문의 내용"},{"admin_note","신청서 메모"},{"reserved_time","예약 시간"},{"created_at","등록 시각"},{"updated_at","수정 시각"},{"last_activity_at","최근 처리"},{"content","메모 내용"},{"paid_amount","준 금액"},{"received_amount","받은 금액"},{"flag","고객 표시"},{"title","제목"},{"views","조회수"},{"phone_clicks","전화 버튼 클릭"},{"requests","온라인 신청"},{"source","유입 경로 코드"},{"visitors","방문자"}};return names.ContainsKey(name)?names[name]:name;}
  void EditDay(){var w=Dialog("날짜별 메모·금액",600,660);var p=(StackPanel)((ScrollViewer)w.Content).Content;p.Children.Add(Text("날짜별 업무 기록",22,"#18334E",true));var date=Field(p,"날짜 (YYYY-MM-DD)",KoreaNow().ToString("yyyy-MM-dd"),10);var paid=Field(p,"준 금액 (원)","0",12);var received=Field(p,"받은 금액 (원)","0",12);var memo=Field(p,"그날의 메모", "",2000,true);var error=Text("",13,"#B3261E");Gap(p,error,12);
   var load=new Button{Content="이 날짜의 기존 기록 불러오기",Padding=new Thickness(12)};Gap(p,load,12);load.Click+=async(s,e)=>{if(demo)return;load.IsEnabled=false;try{DateTime d;if(!DateTime.TryParseExact(date.Text,"yyyy-MM-dd",null,System.Globalization.DateTimeStyles.None,out d))throw new Exception("날짜를 YYYY-MM-DD로 입력해 주세요.");var records=Json.Rows(await api.Call("/api/admin/native-day-finances?month="+date.Text.Substring(0,7)),"records");var r=records.FirstOrDefault(v=>Json.S(v,"date")==date.Text);paid.Text=Json.S(r,"paidAmount");received.Text=Json.S(r,"receivedAmount");if(r==null){paid.Text="0";received.Text="0";}var notes=Json.Rows(await api.Call("/api/admin/native-day-memos"),"memos");memo.Text=Json.S(notes.FirstOrDefault(v=>Json.S(v,"date")==date.Text),"content");error.Text="기존 기록을 불러왔습니다.";}catch(Exception ex){error.Text=ex.Message;}finally{load.IsEnabled=true;}};
   var save=new Button{Content="날짜 기록 저장",Padding=new Thickness(14),Margin=new Thickness(0,12,0,0)};p.Children.Add(save);save.Click+=async(s,e)=>{if(demo)return;long a,b;DateTime d;if(!DateTime.TryParseExact(date.Text,"yyyy-MM-dd",null,System.Globalization.DateTimeStyles.None,out d)||!Int64.TryParse(paid.Text,out a)||!Int64.TryParse(received.Text,out b)||a<0||b<0){error.Text="날짜와 0 이상의 원 단위 금액을 확인해 주세요.";return;}if(MessageBox.Show(w,date.Text+" 날짜의 금액과 메모를 현재 입력한 내용으로 저장할까요? 기존 기록은 덮어씁니다.","날짜 기록 저장",MessageBoxButton.YesNo,MessageBoxImage.Question,MessageBoxResult.No)!=MessageBoxResult.Yes)return;save.IsEnabled=false;try{await api.Call("/api/admin/native-day-finances","POST",Json.Obj("date",date.Text,"paidAmount",a,"receivedAmount",b,"content",NormalLines(memo.Text)));w.Close();await Run(Refresh);}catch(Exception ex){error.Text=ex.Message;save.IsEnabled=true;}};w.ShowDialog();}
  static string CsvValue(string value){if(value.Length>0&&"=+-@\t\r".IndexOf(value[0])>=0)value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}
  static string Csv(List<Dictionary<string,object>> rows,string[] keys){var b=new StringBuilder();b.AppendLine(String.Join(",",keys.Select(k=>CsvValue(ColumnName(k)))));foreach(var r in rows)b.AppendLine(String.Join(",",keys.Select(k=>CsvValue(Json.S(r,k)))));return b.ToString();}
  SaveFileDialog SaveDialog(string name,string filter){return new SaveFileDialog{FileName=name,Filter=filter,OverwritePrompt=true,InitialDirectory=Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments)};}
  async Task<List<Dictionary<string,object>>> AllRows(string key){var rows=new List<Dictionary<string,object>>();int p=0;while(true){if(demo)return key==tableKey?Json.Rows(tableData,"rows"):new List<Dictionary<string,object>>();var result=await api.Call("/api/admin/desktop?mode=data&table="+key+"&page="+p++);rows.AddRange(Json.Rows(result,"rows"));if(rows.Count>=Json.N(result,"total"))return rows;if(p>5000)throw new Exception("자료가 매우 많습니다. 표별로 나눠 백업해 주세요.");SetStatus("백업 준비: "+TableNames[Array.IndexOf(TableKeys,key)]+" "+Num(rows.Count)+"건",false);}}
  async Task ExportRequests(){var dialog=SaveDialog("헌옷일번지_신청서_"+KoreaNow().ToString("yyyyMMdd")+".csv","CSV 파일|*.csv");if(dialog.ShowDialog(win)!=true)return;var keys=new[]{"name","phone","address","date","timeSlot","pickupMethod","amount","status","reservedTime","adminNote","message"};File.WriteAllText(dialog.FileName,Csv(requests,keys),new UTF8Encoding(true));SetStatus("신청서 CSV를 저장했습니다. 고객 정보가 포함되어 있습니다.",false);await Task.FromResult(0);}
  async Task ExportTable(){var dialog=SaveDialog("헌옷일번지_"+tableKey+"_"+KoreaNow().ToString("yyyyMMdd")+".csv","CSV 파일|*.csv");if(dialog.ShowDialog(win)!=true)return;var rows=await AllRows(tableKey);var keys=((IEnumerable)tableData["columns"]).Cast<object>().Select(Convert.ToString).ToArray();File.WriteAllText(dialog.FileName,Csv(rows,keys),new UTF8Encoding(true));SetStatus("선택한 자료 전체를 CSV로 저장했습니다.",false);}
  async Task Backup(){if(!Confirm("업무 자료 백업","신청서·메모·금액·통계를 JSON 파일로 저장합니다. 고객 개인정보가 포함됩니다. 본인만 접근할 수 있는 폴더에 저장해 주세요."))return;var dialog=SaveDialog("헌옷일번지_업무백업_"+KoreaNow().ToString("yyyyMMdd_HHmm")+".json","JSON 백업|*.json");if(dialog.ShowDialog(win)!=true)return;var tables=new Dictionary<string,object>();foreach(var key in TableKeys)tables[key]=await AllRows(key);var backup=Json.Obj("format","heonot-desk-backup","version",1,"exportedAt",DateTime.UtcNow.ToString("o"),"tables",tables);File.WriteAllText(dialog.FileName,Json.Write(backup),new UTF8Encoding(true));SetStatus("전체 업무 자료 백업이 완료되었습니다. 자동 복원용 DB 파일이 아닌 확인·보관용 JSON입니다.",false);}
